/* a + b (b may be 0; a 0 byte between them for HELLO's name and link) */
static void ann_send(uint32_t cmd, uint32_t flags, const char *a, const char *b)
{
    char w[ANN_MAX + 2];
    uint8_t f[8 + ANN_MAX];
    uint32_t n = 0, k = 0, i, two = cmd == ANN_HELLO;
    for (; a; a = b, b = 0) {
        while (*a && k < ANN_MAX)
            w[k++] = *a++;
        if (*a) {                             /* too long: back to the last space */
            while (k && w[k - 1] != ' ')
                k--;
            while (k && w[k - 1] == ' ')
                k--;
            break;
        }
        if (two && b)
            w[k++] = 1;                       /* (the 0 between: put in as the frame is written) */
    }
    w[k] = 0;
    f[n++] = 0xF0;
    f[n++] = ANN_H0;
    f[n++] = ANN_H1;
    f[n++] = ANN_H2;
    f[n++] = (uint8_t)cmd;
    f[n++] = (uint8_t)(flags & 0x7Fu);
    for (i = 0; w[i]; i++)
        f[n++] = w[i] == 1 && two ? 0 : (uint8_t)w[i] & 0x7Fu;
    f[n++] = 0xF7;
    ann_wire_send(f, n);
}

static void ev_put(uint32_t type, uint32_t val)
{
    uint32_t w = evq_w;
    if (w - evq_r >= EVQ)
        return;
    evq[w % EVQ] = type << 24 | (val & 0xFFFFFFu);
    evq_w = w + 1u;
}

/* small number text without printf */
static void itoa_s(int v, char *b)
{
    char t[12];
    int n = 0;
    unsigned u = (unsigned)(v < 0 ? -v : v);
    do
        t[n++] = (char)('0' + u % 10u);
    while ((u /= 10u) && n < 11);
    if (v < 0)
        *b++ = '-';
    while (n)
        *b++ = t[--n];
    *b = 0;
}

static void curve_draw(int c, rgb_t col, float width, float alpha, float glowk, int npts)
{
    float p[2 * 96];
    int i, n = 0, from = c == 3 ? 1 : 0;
    for (i = from; i < npts; i++) {
        float t = (float)i / (npts - 1);
        p[2 * n] = GX0 + (GX1 - GX0) * t;
        p[2 * n + 1] = GY1 - (GY1 - GY0) * curve_of(c, t);
        n++;
    }
    mask_clear(GX0 - 12, GY0 - 12, GX1 + 13, GY1 + 13);
    mask_line(p, n, width);
    if (glowk > 0) {
        mask_glow(2.0f, col, glowk);
        mask_clear(GX0 - 12, GY0 - 12, GX1 + 13, GY1 + 13);
        mask_line(p, n, width);
    }
    mask_fill(col, alpha);
}

static int midi_enqueue(uint32_t pkt, uint32_t source)
{
    uint32_t at = mi_w % MQ;
    if (midi_in_overflow)
        return 0;
    if (mi_w - mi_r >= MQ) {
        midi_in_overflow = 1;
        return 0;
    }
    midi_in_q[at] = pkt;
    midi_in_ms[at] = fm1_ms;
    midi_in_source[at] = (uint8_t)source;
    RING_PUBLISH();
    mi_w++;
    return 1;
}

static int ota_erase(uint32_t off)
{
    if (off < T_AREA || off >= T_END || (off & 0xFFFu)) { bad_erase++; return -8; }
    memset(nor + off, 0xFF, 4096);
    return 0;
}

static int ota_send_msg(uint32_t cmd, const uint8_t *body, uint32_t n)   /* n <= 32 */
{
    uint32_t i, s = 0, w;
    ota_msg[0] = 0;
    ota_msg[1] = 0x59;
    ota_msg[2] = (uint8_t)cmd;
    ota_msg[3] = (uint8_t)n;
    ota_msg[4] = 0;
    ota_msg[5] = 0;
    for (i = 0; i < n; i++) {
        ota_msg[6 + i] = body[i];
        s += body[i];
    }
    ota_msg[6 + n] = (uint8_t)~s;
    ota_wire[0] = 0xF0;
    w = 1u + ota_pack7(ota_msg, 7u + n, ota_wire + 1);
    ota_wire[w++] = 0xF7;
    return ota_wire_send(ota_wire, w);
}

void erk_note_off(int key)
{
    int i;
    key -= ERK_KEY0;
    if (key >= 0 && key < ERK_KEYS)
        pad_off(key, sus || key_sost(key));
    for (i = 0; i < ERK_VOICES + ERK_DYING; i++) {
        voice *v = &vc[i];
        if (v->key == key && v->state == V_ON) {
            if (sus || (v->flags & F_SOST))
                v->state = V_SUST;                    /* the pedal (or the sostenuto) holds its damper up */
            else
                release(v);
        }
    }
}

void erk_set_tone(int tone, int brilliance_q15, int una_q15)
{
    float b = ((float)clampi(brilliance_q15, 0, 32767) / 32768.0f - 0.5f) * 2.0f;   /* -1 .. +1 */
    tone = clampi(tone, 0, ERK_NTONES - 1);
    st.bscale = (int32_t)(4096.0f * TONE[tone].bright * exp2_f(0.7f * b));
    st.g_lo = (int32_t)(4096.0f * (exp2_f(TONE[tone].lo_db * 0.1660964f) - 1.0f));    /* dB / 20 log2 10 */
    st.g_hi = (int32_t)(4096.0f * (exp2_f((TONE[tone].hi_db + 6.0f * b) * 0.1660964f) - 1.0f));
    st.res_scale = (int32_t)(32767.0f * TONE[tone].res);
    st.detune = TONE[tone].detune;
    st.una = clampi(una_q15, 0, 32767);
}
